74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Dedicated audit logger. On a successful create an audit line carrying the new owner's id,
81	     * {@code customerCode}, {@code registrationDate} and {@code membershipLevel} is emitted to the
82	     * logger named {@code AUDIT}.
83	     */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
85	
86	    /**
87	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
88	     * at least one dot and no whitespace on either side.
89	     */
90	    private static final Pattern EMAIL_PATTERN =
91	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
92	
93	    /**
94	     * Disposable email domains that an owner's email may not use. An email whose domain (the part
95	     * after the {@code @}, compared case-insensitively) is on this list is rejected with a 400
96	     * response naming {@code email}.
97	     */
98	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
99	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
100	
101	    /**
102	     * Common street-type abbreviations expanded during address normalization. Keys are the
103	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
104	     * expanded form.
105	     */
106	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
107	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
108	
109	    /**
110	     * Required national-number length per E.164 country code (the digits that follow the country
111	     * code). {@code '+61'} (Australia) requires 9 national digits; {@code '+1'} (NANP) requires 10.
112	     * A country code that is not listed here is not length-checked, keeping other numbers accepted.
113	     */
114	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH =
115	        Map.of("1", 10, "61", 9);
116	
117	    /**
118	     * Inclusive 4-digit postcode range allowed for each known region, keyed by the region an owner's
119	     * city derives to (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD): NSW 2000-2099, VIC
120	     * 3000-3099, QLD 4000-4099. A city that derives to no known region ({@code "UNKNOWN"}) is not in
121	     * this table and accepts any 4-digit postcode.
122	     */
123	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
124	        "NSW", new int[] {2000, 2099},
125	        "VIC", new int[] {3000, 3099},
126	        "QLD", new int[] {4000, 4099});
127	
128	    /**
129	     * The maximum number of owners a single city may contain. A create request for a city that
130	     * already holds this many owners is rejected with a 409 response.
131	     */
132	    private static final int MAX_OWNERS_PER_CITY = 50;
133	
134	    /**
135	     * The maximum number of owners that may be registered in a single day. A create request made
136	     * once this many owners already carry today's {@code registrationDate} is rejected with a 429
137	     * response.
138	     */
139	    private static final int MAX_OWNERS_PER_DAY = 100;
140	
141	    /**
142	     * The number of owners that must already carry a day's {@code registrationDate} before a create
143	     * for that day is flagged as a bulk signup. Once more than this many owners already exist for the
144	     * day, the new owner is created with {@code bulkSignupWarning} set to {@code true}.
145	     */
146	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
147	
148	    /**
149	     * The tenure, in elapsed fiscal years, an owner must exceed to reach {@code membershipLevel} 4.
150	     * Tenure accrues from membership, so a newly created owner (zero tenure) never clears this
151	     * threshold and is therefore capped at level 3 on create.
152	     */
153	    private static final int TENURE_LEVEL_THRESHOLD_FISCAL_YEARS = 1;
154	
155	    /**
156	     * The HTTP header carrying a client-supplied idempotency token for owner creation. When a create
157	     * request repeats with a token already seen, the originally created owner is returned instead of
158	     * a second owner being created.
159	     */
160	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
161	
162	    /**
163	     * Remembers the owner id created for each seen {@code Idempotency-Key}, so a repeated create with
164	     * an already-seen key returns the originally created owner (200) instead of creating a duplicate.
165	     */
166	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
