211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
214	        String idempotencyKey = idempotencyKey();
215	        if (idempotencyKey != null) {
216	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
217	            if (existingId != null) {
218	                Owner existing = this.clinicService.findOwnerById(existingId);
219	                if (existing != null) {
220	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
221	                }
222	            }
223	        }
224	        normalizeAddress(ownerFieldsDto);
225	        validateRequiredFields(ownerFieldsDto);
226	        normalizeTelephone(ownerFieldsDto);
227	        normalizeEmail(ownerFieldsDto);
228	        validatePostcode(ownerFieldsDto);
229	        String householdId = computeHouseholdId(ownerFieldsDto);
230	        rejectDuplicate(ownerFieldsDto);
231	        rejectCityAtCapacity(ownerFieldsDto);
232	        resolveRegistrationDate(ownerFieldsDto);
233	        rejectDailyLimitReached(ownerFieldsDto.getRegistrationDate());
234	        HttpHeaders headers = new HttpHeaders();
235	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
236	        owner.setHouseholdId(householdId);
237	        assignCustomerCode(owner);
238	        assignMembershipNumber(owner);
239	        assignNamesakeCount(owner);
240	        assignBulkSignupWarning(owner);
241	        assignPossibleDuplicate(owner, ownerFieldsDto);
242	        assignHouseholdMembership(owner);
243	        assignMembership(owner);
244	        this.clinicService.saveOwner(owner);
245	        if (idempotencyKey != null) {
246	            this.idempotentCreates.put(idempotencyKey, owner.getId());
247	        }
248	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
249	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
250	            owner.getMembershipNumber());
251	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
252	        headers.setLocation(UriComponentsBuilder.newInstance()
253	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
254	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
260	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
261	        if (currentOwner == null) {
262	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	        }
264	        normalizeAddress(ownerFieldsDto);
265	        currentOwner.setAddress(ownerFieldsDto.getAddress());
266	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
267	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
268	        currentOwner.setCity(ownerFieldsDto.getCity());
269	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
270	        currentOwner.setLastName(ownerFieldsDto.getLastName());
271	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
272	        normalizeEmail(ownerFieldsDto);
273	        currentOwner.setEmail(ownerFieldsDto.getEmail());
274	        this.clinicService.saveOwner(currentOwner);
275	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
276	    }
