278	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
279	    @Transactional
280	    @Override
281	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
282	        Owner owner = this.clinicService.findOwnerById(ownerId);
283	        if (owner == null) {
284	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
285	        }
286	        owner.setDeleted(true);
287	        this.clinicService.saveOwner(owner);
