291	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
292	    @Override
293	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
294	        Owner owner = this.clinicService.findOwnerById(ownerId);
295	        if (owner == null) {
296	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
297	        }
298	        HttpHeaders headers = new HttpHeaders();
299	        Pet pet = petMapper.toPet(petFieldsDto);
300	        owner.setId(ownerId);
301	        pet.setOwner(owner);
302	        pet.getType().setName(null);
303	        this.clinicService.savePet(pet);
304	        PetDto petDto = petMapper.toPetDto(pet);
305	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
306	            .buildAndExpand(pet.getId()).toUri());
307	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
308	    }
309	
310	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
311	    @Override
312	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
313	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
314	        if (currentOwner != null) {
315	            Pet currentPet = this.clinicService.findPetById(petId);
316	            if (currentPet != null) {
317	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
318	                currentPet.setName(petFieldsDto.getName());
319	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
320	                this.clinicService.savePet(currentPet);
321	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
322	            }
323	        }
324	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
325	    }
