327	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
328	    @Override
329	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
330	        HttpHeaders headers = new HttpHeaders();
331	        Visit visit = visitMapper.toVisit(visitFieldsDto);
332	        Pet pet = new Pet();
333	        pet.setId(petId);
334	        visit.setPet(pet);
335	        this.clinicService.saveVisit(visit);
336	        VisitDto visitDto = visitMapper.toVisitDto(visit);
337	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
338	            .buildAndExpand(visit.getId()).toUri());
339	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
340	    }
341	
342	
343	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
344	    @Override
345	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
346	        Owner owner = this.clinicService.findOwnerById(ownerId);
347	        if (owner != null) {
348	            Pet pet = owner.getPet(petId);
349	            if (pet != null) {
350	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
351	            }
352	        }
353	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
354	    }
355	
356	    /**
357	     * Returns the trimmed {@code Idempotency-Key} header of the current request, or {@code null} when
358	     * the header is absent, blank or there is no active request. A present key opts a create into the
359	     * idempotent-repeat behaviour tracked by {@link #idempotentCreates}.
360	     */
361	    private String idempotencyKey() {
362	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
363	            return null;
364	        }
365	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
366	        if (key == null || key.trim().isEmpty()) {
367	            return null;
368	        }
369	        return key.trim();
370	    }
371	
372	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
373	        List<String> missingFields = new ArrayList<>();
374	        if (isBlank(ownerFieldsDto.getFirstName())) {
375	            missingFields.add("firstName");
376	        }
377	        if (isBlank(ownerFieldsDto.getLastName())) {
378	            missingFields.add("lastName");
379	        }
380	        if (isBlank(ownerFieldsDto.getAddress())) {
381	            missingFields.add("address");
382	        }
383	        if (isBlank(ownerFieldsDto.getCity())) {
384	            missingFields.add("city");
