398	    /**
399	     * Normalizes an owner's address on create, supporting both the structured form
400	     * ({@code addressLine1} plus optional {@code addressLine2}) and the flat {@code address} form kept
401	     * for backward compatibility. Whichever fields are supplied are canonicalized in place - trimmed,
402	     * internal whitespace runs collapsed to a single space, upper-cased and common street-type
403	     * abbreviations expanded as whole tokens ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
404	     * {@code AVE}->{@code AVENUE}). The canonical {@code addressLine1}/{@code addressLine2} are written
405	     * back, and the composed {@code address} - the normalized {@code addressLine1} with a single space
406	     * and the normalized {@code addressLine2} appended when present, falling back to the normalized
407	     * flat {@code address} when no structured line is given - is written onto the request so it is what
408	     * gets validated, compared, stored and returned. Running before the required-field check means an
409	     * address that is blank in both forms after normalization is rejected like a missing one.
410	     */
411	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
412	        String line1 = canonicalAddress(ownerFieldsDto.getAddressLine1());
413	        String line2 = canonicalAddress(ownerFieldsDto.getAddressLine2());
414	        String flat = canonicalAddress(ownerFieldsDto.getAddress());
415	        ownerFieldsDto.setAddressLine1(line1);
416	        ownerFieldsDto.setAddressLine2(line2);
417	        ownerFieldsDto.setAddress(composeAddress(line1, line2, flat));
418	    }
