420	    /**
421	     * Composes the effective address, preferring the structured form: when {@code line1} is present
422	     * (non-blank) the result is {@code line1}, with a single space and {@code line2} appended when
423	     * {@code line2} is present; otherwise the flat {@code address} is used. All three inputs are
424	     * expected to be already canonicalized. Returns the flat value (which may be {@code null} or blank,
425	     * left for the required-field check to reject) when no structured line is supplied.
426	     */
427	    private static String composeAddress(String line1, String line2, String flat) {
428	        if (line1 != null && !line1.isBlank()) {
429	            if (line2 != null && !line2.isBlank()) {
430	                return line1 + " " + line2;
431	            }
432	            return line1;
433	        }
434	        return flat;
435	    }
