437	    /**
438	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
439	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
440	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
441	     * address is returned unchanged, making it safe to apply to stored values during comparison.
442	     */
443	    private static String canonicalAddress(String address) {
444	        if (address == null) {
445	            return null;
446	        }
447	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
448	        if (collapsed.isEmpty()) {
449	            return "";
450	        }
451	        String[] tokens = collapsed.split(" ");
452	        StringBuilder sb = new StringBuilder(collapsed.length());
453	        for (int i = 0; i < tokens.length; i++) {
454	            if (i > 0) {
455	                sb.append(' ');
456	            }
457	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
458	        }
459	        return sb.toString();
460	    }
