462	    /**
463	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
464	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
465	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
466	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
467	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
468	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
469	     * written back onto the request so it is what gets stored and returned. Any value that cannot
470	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
471	     * {@code telephone}.
472	     */
473	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
474	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
475	    }
