477	    /**
478	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
479	     * (400) naming {@code telephone} when it cannot form a valid number.
480	     */
481	    private static String toE164(String telephone) {
482	        if (telephone == null) {
483	            throw new InvalidOwnerFieldsException(List.of("telephone"));
484	        }
485	        boolean hasCountryCode = telephone.trim().startsWith("+");
486	        String digits = telephone.replaceAll("\\D", "");
487	        String countryCode;
488	        String national;
489	        if (hasCountryCode) {
490	            countryCode = matchCountryCode(digits);
491	            national = digits;
492	        } else {
493	            countryCode = "61";
494	            if (digits.startsWith("0")) {
495	                digits = digits.substring(1);
496	            }
497	            national = "61" + digits;
498	        }
499	        if (!national.matches("[0-9]{8,15}")) {
500	            throw new InvalidOwnerFieldsException(List.of("telephone"));
501	        }
502	        if (countryCode != null) {
503	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
504	            if (requiredLength != null
505	                && national.length() - countryCode.length() != requiredLength) {
506	                throw new InvalidOwnerFieldsException(List.of("telephone"));
507	            }
508	        }
509	        return "+" + national;
510	    }
511	
512	    /**
513	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
514	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
515	     * the number is not length-checked against a country.
516	     */
517	    private static String matchCountryCode(String digits) {
518	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
519	            .filter(digits::startsWith)
520	            .max(Comparator.comparingInt(String::length))
521	            .orElse(null);
522	    }
