524	    /**
525	     * Rejects creating an owner that duplicates an existing one on the derived {@code identityKey} -
526	     * the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' +
527	     * soundex(lastName)} (see {@link IdentityKey}). An exact key match means the same telephone, email
528	     * and same-sounding surname, i.e. the same person re-registering; because the telephone is part of
529	     * the key, two people who merely share a surname (and postcode) but carry different telephones no
530	     * longer collide here - they are surfaced as a soft match instead (see
531	     * {@link #assignPossibleDuplicate}). This single identity key is the only hard-duplicate rule; the
532	     * computed {@code householdId} no longer contributes a separate 409. A match is a 409.
533	     *
534	     * <p>Owners flagged {@code deleted} (soft-deleted via {@code DELETE /api/owners/{id}}) are skipped
535	     * entirely, so a normally-blocking duplicate is allowed when the only matching owner has been
536	     * deleted.
537	     *
538	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block. The incoming telephone
539	     * and email have already been normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}
540	     * (the email-domain blocklist applies first, in {@link #normalizeEmail}); each existing owner's key
541	     * is derived the same way before comparison. A match results in a 409 response naming
542	     * {@code identityKey}.
543	     */
544	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto) {
545	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
546	            return;
547	        }
548	        String identityKey = IdentityKey.of(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(),
549	            ownerFieldsDto.getLastName());
550	        for (Owner existing : this.clinicService.findAllOwners()) {
551	            if (Boolean.TRUE.equals(existing.getDeleted())) {
552	                continue;
553	            }
554	            if (identityKey.equals(existingIdentityKey(existing))) {
555	                throw new DuplicateOwnerIdentityException(identityKey);
556	            }
557	        }
558	    }
