560	    /**
561	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
562	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
563	     * the stored email is lower-cased and the stored last name is reduced to its Soundex code, exactly
564	     * as {@link IdentityKey#of} does for an incoming request.
565	     */
566	    private static String existingIdentityKey(Owner existing) {
567	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
568	        return IdentityKey.of(telephone, existing.getEmail(), existing.getLastName());
569	    }
