636	    /**
637	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
638	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
639	     * written back onto the request so that is what gets stored and returned. A present but invalid
640	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
641	     */
642	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
643	        String email = ownerFieldsDto.getEmail();
644	        if (email == null) {
645	            return;
646	        }
647	        String trimmed = email.trim();
648	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
649	            throw new InvalidOwnerFieldsException(List.of("email"));
