659	    /**
660	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
661	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
662	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
663	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
664	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
665	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
666	     * as-is so it is stored and returned.
667	     */
668	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
669	        String postcode = ownerFieldsDto.getPostcode();
670	        if (postcode == null) {
671	            return;
672	        }
673	        if (!postcode.matches("[0-9]{4}")) {
674	            throw new InvalidOwnerFieldsException(List.of("postcode"));
675	        }
676	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
677	        if (range != null) {
678	            int value = Integer.parseInt(postcode);
679	            if (value < range[0] || value > range[1]) {
680	                throw new InvalidOwnerFieldsException(List.of("postcode"));
681	            }
682	        }
