685	    /**
686	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
687	     * day. When the caller supplies no value it defaults to the server's current date; a value
688	     * provided in the request is kept. A supplied value later than the server's current date is
689	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
690	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
691	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
692	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
693	     * every value derived from the registration date is based on.
694	     */
695	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
696	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
697	        if (effective == null) {
698	            effective = LocalDate.now();
699	        }
700	        else if (effective.isAfter(LocalDate.now())) {
701	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
702	        }
703	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
704	    }
