706	    /**
707	     * The fixed public-holiday calendar. A registration date landing on one of these days is rolled
708	     * forward, just like a weekend, until it reaches a non-holiday business day.
709	     */
710	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
711	        LocalDate.of(2026, 1, 1),
712	        LocalDate.of(2026, 1, 26),
713	        LocalDate.of(2026, 4, 25),
714	        LocalDate.of(2026, 12, 25),
715	        LocalDate.of(2026, 12, 28));
716	
717	    /**
718	     * Rolls a date forward onto a business day: a Saturday, Sunday or listed public holiday is
719	     * advanced one day at a time until it reaches the next non-holiday business day; a weekday that
720	     * is not a holiday is returned unchanged.
721	     */
722	    private static LocalDate toBusinessDay(LocalDate date) {
723	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
724	            date = date.plusDays(1);
725	        }
726	        return date;
727	    }
728	
729	    /**
730	     * Returns whether the given date falls on a Saturday or Sunday.
731	     */
732	    private static boolean isWeekend(LocalDate date) {
733	        return switch (date.getDayOfWeek()) {
734	            case SATURDAY, SUNDAY -> true;
735	            default -> false;
736	        };
737	    }
