739	    /**
740	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
741	     * {@code REGION} is the region the owner's identity derives to from its postcode (falling back to
742	     * the city table when the postcode is absent or in no known range) and {@code HASH8} is the first
743	     * eight upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
744	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The telephone has already been normalized to
745	     * E.164 form by {@link #normalizeTelephone}. There is no per-city sequence: the identity is a
746	     * pure function of region, telephone and last name.
747	     */
748	    private void assignCustomerCode(Owner owner) {
749	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
750	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
751	        owner.setCustomerCode(deduplicateCustomerCode(region + "-" + hash8));
752	    }
