754	    /**
755	     * Returns {@code customerCode} unchanged when no existing owner already carries it; otherwise
756	     * appends {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not held by
757	     * any existing owner. Compared against the pre-existing owners, so the returned code is unique
758	     * among them.
759	     */
760	    private String deduplicateCustomerCode(String customerCode) {
761	        Set<String> existing = new HashSet<>();
762	        for (Owner owner : this.clinicService.findAllOwners()) {
763	            if (owner.getCustomerCode() != null) {
764	                existing.add(owner.getCustomerCode());
765	            }
766	        }
767	        if (!existing.contains(customerCode)) {
768	            return customerCode;
769	        }
770	        int n = 2;
771	        while (existing.contains(customerCode + "-" + n)) {
772	            n++;
773	        }
774	        return customerCode + "-" + n;
775	    }
