808	    /**
809	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
810	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
811	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
812	     * {@value #TENURE_LEVEL_THRESHOLD_FISCAL_YEARS} elapsed fiscal year. The points are then mapped to a level of 1 (0-1
813	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
814	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
815	     * tenure, so the tenure bonus never applies on create.
816	     */
817	    private void assignMembership(Owner owner) {
818	        int points = 0;
819	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
820	            points += 2;
821	        }
822	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
823	            points += 1;
824	        }
825	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
826	            points += 2;
827	        }
828	        if (tenureFiscalYears(owner) > TENURE_LEVEL_THRESHOLD_FISCAL_YEARS) {
829	            points += 3;
830	        }
831	        owner.setMembershipPoints(points);
832	        owner.setMembershipLevel(capMembershipLevelByHousehold(owner, membershipLevelForPoints(points)));
833	    }
