835	    /**
836	     * Caps a newly derived {@code membershipLevel} so it cannot exceed one above the current maximum
837	     * {@code membershipLevel} among the new owner's existing household members - the pre-existing owners
838	     * already carrying the same {@code householdId}. When the owner belongs to no household, or has no
839	     * existing household member, no cap applies and the derived level is returned unchanged. Runs after
840	     * {@link #assignHouseholdMembership} so the owner's {@code householdId} is settled.
841	     */
842	    private int capMembershipLevelByHousehold(Owner owner, int derivedLevel) {
843	        String householdId = owner.getHouseholdId();
844	        if (householdId == null || householdId.isBlank()) {
845	            return derivedLevel;
846	        }
847	        Integer maxHouseholdLevel = null;
848	        for (Owner existing : this.clinicService.findAllOwners()) {
849	            if (householdId.equals(existing.getHouseholdId()) && existing.getMembershipLevel() != null
850	                && (maxHouseholdLevel == null || existing.getMembershipLevel() > maxHouseholdLevel)) {
851	                maxHouseholdLevel = existing.getMembershipLevel();
852	            }
853	        }
854	        if (maxHouseholdLevel == null) {
855	            return derivedLevel;
856	        }
857	        return Math.min(derivedLevel, maxHouseholdLevel + 1);
858	    }
