860	    /**
861	     * Maps {@code membershipPoints} to a {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for
862	     * 4-5, and 4 for 6 or more points.
863	     */
864	    private int membershipLevelForPoints(int points) {
865	        if (points <= 1) {
866	            return 1;
867	        }
868	        if (points <= 3) {
869	            return 2;
870	        }
871	        if (points <= 5) {
872	            return 3;
873	        }
874	        return 4;
875	    }
