905	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
906	     * owner has already cleared the duplicate block, so it is not a hard duplicate. It is flagged as a
907	     * possible duplicate when an existing owner has the same {@code soundex(lastName)} and the same
908	     * {@code postcode} (a present, exact match) yet a <em>different</em> {@code identityKey} - the
909	     * soft-match now keys on the surname sound and postcode rather than an exact last name, and fires
910	     * precisely for the near-miss the identity key lets through (same household surname and postcode
911	     * but a different telephone, so a different key). When such an owner exists,
912	     * {@code possibleDuplicate} is set to {@code true} and {@code possibleDuplicateOf} to that owner's
913	     * id (the lowest id when several match); otherwise {@code possibleDuplicate} is {@code false} and
914	     * {@code possibleDuplicateOf} is left {@code null}. Computed before the new owner is persisted, so
915	     * it considers only the pre-existing owners.
916	     *
917	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
918	     * has deliberately opted into an existing household, so its shared last name and postcode are
919	     * expected rather than a suspected duplicate.
920	     */
921	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
922	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
923	            owner.setPossibleDuplicate(false);
924	            owner.setPossibleDuplicateOf(null);
925	            return;
926	        }
927	        String postcode = owner.getPostcode();
928	        String soundex = IdentityKey.soundex(owner.getLastName());
929	        String identityKey = IdentityKey.of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
930	        Integer matchId = null;
931	        if (postcode != null && !postcode.isBlank()) {
932	            for (Owner existing : this.clinicService.findAllOwners()) {
933	                if (soundex.equals(IdentityKey.soundex(existing.getLastName()))
934	                    && postcode.equals(existing.getPostcode())
935	                    && !identityKey.equals(existingIdentityKey(existing))
936	                    && existing.getId() != null
937	                    && (matchId == null || existing.getId() < matchId)) {
938	                    matchId = existing.getId();
939	                }
940	            }
941	        }
942	        owner.setPossibleDuplicate(matchId != null);
943	        owner.setPossibleDuplicateOf(matchId);
944	    }
945	
946	    /**
947	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
948	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
949	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
950	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
951	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
952	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
953	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
954	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
955	     * ({@link #assignHouseholdMembership}).
956	     */
957	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
958	        String postcode = ownerFieldsDto.getPostcode();
959	        if (postcode == null || postcode.isBlank()) {
960	            return null;
961	        }
962	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
963	        return shaHexUpper(lastName + "|" + postcode, 12);
964	    }
965	
966	    /**
967	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
968	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
969	     * every existing owner already carrying the same identifier. Runs after the owner's
970	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
971	     * Left {@code null} when the owner belongs to no household.
972	     */
973	    private void assignHouseholdMembership(Owner owner) {
974	        String householdId = owner.getHouseholdId();
975	        if (householdId == null || householdId.isBlank()) {
976	            owner.setHouseholdMemberCount(null);
977	            return;
978	        }
979	        int count = 1;
980	        for (Owner existing : this.clinicService.findAllOwners()) {
981	            if (householdId.equals(existing.getHouseholdId())) {
982	                count++;
983	            }
984	        }
985	        owner.setHouseholdMemberCount(count);
986	    }
987	
988	    /**
989	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
990	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
991	     * identifier, both stable functions of their inputs.
992	     */
993	    private static String shaHexUpper(String input, int length) {
994	        try {
995	            byte[] digest = MessageDigest.getInstance("SHA-256")
996	                .digest(input.getBytes(StandardCharsets.UTF_8));
997	            StringBuilder hex = new StringBuilder(digest.length * 2);
998	            for (byte b : digest) {
999	                hex.append(String.format("%02x", b));
1000	            }
1001	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
1002	        } catch (NoSuchAlgorithmException ex) {
1003	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
1004	        }
1005	    }
1006	}
